            auto fullMana=prepare("Hmkg");auto b=session.units().at(fullMana.bits);call("SetWidgetLife",{fullMana,real(100)});call("SetUnitState",{fullMana,vm.handle("unitstate",2),vm.real(b->maxMana)});auto maximumMana=number(b->maxMana);call("set_combined_remove",{vm.boolean(true)});use(fullMana);require(number(b->life)==237 && number(b->mana)==maximumMana && vm.global("combinedUses").bits==3,"Full mana or reentrant item deletion lost health or repeated event");
            call("set_combined_remove",{vm.boolean(false)});auto transfer=prepare("Hblm");auto moved=session.units().at(transfer.bits);call("SetWidgetLife",{transfer,real(100)});call("SetUnitState",{transfer,vm.handle("unitstate",2),real(100)});auto during=call("UnitAddItemById",{transfer,type("I0CM")});require(during.bits,"Cannot create callback fixture item");call("watch_combined_life",{transfer,during});require(call("UnitUseItem",{transfer,during}).bits && !session.items().contains(during.bits) && moved->owner==1 && number(moved->life)==237 && number(moved->mana)==155 && vm.global("combinedEvents").bits==4,"Life callback removal or ownership transfer lost the remaining recovery or use event");
            auto noMana=prepare("Hblm");call("SetWidgetLife",{noMana,real(100)});call("SetUnitState",{noMana,vm.handle("unitstate",2),real(11)});auto costly=call("UnitAddItemById",{noMana,type("I0CM")});require(costly.bits && !call("UnitUseItem",{noMana,costly}).bits && session.items().contains(costly.bits) && vm.global("combinedUses").bits==3,"Combined cost did not reject insufficient mana");auto noNeed=prepare("Hblm");auto c=session.units().at(noNeed.bits);call("SetWidgetLife",{noNeed,vm.real(c->maxLife)});call("SetUnitState",{noNeed,vm.handle("unitstate",2),vm.real(c->maxMana)});auto spare=call("UnitAddItemById",{noNeed,type("I0CM")});require(spare.bits && !call("UnitUseItem",{noNeed,spare}).bits && session.items().contains(spare.bits) && vm.global("combinedUses").bits==3,"Full resources consumed item or fired event");auto unsupported=call("UnitAddItemById",{noNeed,type("I0UN")});bool rejected=false;try{call("UnitUseItem",{noNeed,unsupported});}catch(const std::exception& e){rejected=std::string(e.what()).find("Compound active item abilities")!=std::string::npos;}require(rejected && session.items().contains(unsupported.bits) && vm.global("combinedUses").bits==3,"Unknown combined effect was silently accepted");std::cout<<"PASS combined_recovery_overrides_single_payment_cooldown_and_reentrancy\n";
