            auto first=gem();capture(first);require(!session.items().contains(first.bits) && carrier->soulVictim==hero.bits && victim->soulCaptor==mage.bits && victim->hidden() && victim->paused && carrier->soulItem && session.items().contains(carrier->soulItem) && session.items().at(carrier->soulItem)->holder==mage.bits && vm.global("soulPickups").bits==1,"Soul capture did not replace the consumed gem in a full inventory");auto held=carrier->soulItem;require(call("UnitRemoveAbility",{mage,type("Asou")}).bits && !carrier->soulVictim && !victim->soulCaptor && !victim->hidden() && !victim->paused && !session.items().contains(held),"Removing the soul ability did not release the hero and item");
            call("set_soul_callback",{vm.integer(1)});auto second=gem();capture(second);require(!carrier->soulVictim && !victim->soulCaptor && !victim->hidden() && !victim->paused && vm.global("soulPickups").bits==2,"Pickup callback deleting the soul left a captured hero");call("set_soul_callback",{vm.integer(0)});
            auto third=gem();capture(third);held=carrier->soulItem;require(held && victim->soulCaptor==mage.bits,"Third Soul Gem did not capture the hero");call("KillUnit",{mage});require(!carrier->soulVictim && !victim->soulCaptor && !victim->hidden() && !victim->paused && !session.items().contains(held),"Carrier death did not release the captured hero");std::cout<<"PASS soul_gem_full_inventory_callback_release_and_carrier_death\n";
